insert into public.activities (category, title_en, title_sw, description_en, description_sw) values
  ('Romance','Love Letter Exchange','Kubadilishana Barua za Mapenzi','Write each other a short handwritten letter and read it aloud.','Andikianeni barua fupi ya mkono na kuisoma kwa sauti.'),
  ('Romance','Candlelit Dinner at Home','Chakula cha Mshumaa Nyumbani','Cook together, light candles and eat without phones.','Pikeni pamoja, washeni mishumaa na kula bila simu.'),
  ('Romance','Living Room Slow Dance','Kucheza Taratibu Sebuleni','Put on your song and dance slowly, just the two of you.','Wekeni wimbo wenu na kucheza taratibu, nyinyi wawili tu.'),
  ('Romance','Sunset Walk','Matembezi ya Machweo','Walk hand in hand and watch the sun go down.','Tembeeni mkishikana mikono na kutazama jua likizama.'),
  ('Romance','Breakfast in Bed','Kifungua Kinywa Kitandani','Surprise your partner with breakfast served in bed.','Mshangaze mwenza wako kwa kifungua kinywa kitandani.'),
  ('Romance','Stargazing Night','Usiku wa Kutazama Nyota','Lie outside, look at the stars and share your wishes.','Lalini nje, tazameni nyota na kushirikishana matamanio yenu.'),
  ('Romance','Recreate Your First Date','Rudieni Miadi Yenu ya Kwanza','Go back to where it began, or recreate it at home.','Rudini mlipoanzia, au irudieni nyumbani.'),
  ('Romance','Hand and Shoulder Massage','Kusajiana Mikono na Mabega','Take turns giving a gentle, relaxing massage.','Zamu kwa zamu, sajianeni kwa upole ili kupumzika.'),
  ('Romance','Playlist for Two','Orodha ya Nyimbo za Wawili','Build a playlist of songs that mean something to you both.','Tengenezeni orodha ya nyimbo zenye maana kwenu nyote.'),
  ('Romance','Photo Walk','Matembezi ya Picha','Take photos of each other and of places you love.','Pigianeni picha na kupiga picha za sehemu mnazozipenda.'),
  ('Romance','Picnic for Two','Pikiniki ya Wawili','Pack snacks, find a quiet spot and enjoy the afternoon.','Chukueni vitafunwa, tafuteni sehemu tulivu na kufurahia alasiri.'),
  ('Romance','Five Reasons I Love You','Sababu Tano za Kukupenda','Look into each other''s eyes and share five reasons you love them.','Tazamaneni machoni na kutaja sababu tano za kumpenda mwenza wako.'),
  ('Romance','Blanket Movie Night','Usiku wa Filamu Chini ya Blanketi','Pick a romantic favorite, snuggle up and share popcorn.','Chagueni filamu ya mapenzi mnayoipenda, kaeni karibu na kula popcorn pamoja.'),
  ('Romance','Hidden Love Notes','Ujumbe wa Siri wa Mapenzi','Leave small notes around the house for your partner to find.','Acheni ujumbe mdogo sehemu mbalimbali nyumbani ili mwenza wako aupate.'),
  ('Romance','Cook Their Favorite Meal','Mpikie Chakula Anachopenda','Make your partner''s favorite dish with extra care.','Mpikie mwenza wako chakula anachopenda kwa uangalifu wa ziada.'),
  ('Romance','Relaxing Evening Together','Jioni ya Kupumzika Pamoja','Dim the lights, play soft music and unwind side by side.','Punguzeni mwanga, weka muziki laini na kupumzika pamoja.'),
  ('Romance','Write Our Love Story','Andikeni Hadithi Yetu ya Mapenzi','Write down how you met and what you felt, then swap.','Andikeni mlivyokutana na mlichohisi, kisha mbadilishane.'),
  ('Romance','Twenty-Second Hug','Kumbatio la Sekunde Ishirini','Hug without talking for twenty full seconds and notice how it feels.','Kumbatianeni bila kuongea kwa sekunde ishirini kamili.'),
  ('Romance','Dress-Up Date Night','Usiku wa Miadi kwa Mavazi Bora','Dress in your best outfits and go out like it''s the first time.','Vaeni mavazi yenu bora na kutoka kama mara ya kwanza.'),
  ('Romance','Rainy Day Cuddles','Kukumbatiana Siku ya Mvua','Stay in with tea, blankets and a good conversation.','Kaeni ndani na chai, blanketi na mazungumzo mazuri.'),
  ('Deep Conversations','Dreams in Five Years','Ndoto za Miaka Mitano Ijayo','Describe where you each hope to be in five years.','Elezeni kila mmoja anatarajia kuwa wapi baada ya miaka mitano.'),
  ('Deep Conversations','Biggest Fear','Hofu Kubwa Zaidi','Share a fear you rarely talk about and how your partner can support you.','Shirikisheni hofu mnayoizungumzia mara chache na jinsi mwenza anavyoweza kusaidia.'),
  ('Deep Conversations','What Makes You Feel Loved','Nini Kinakufanya Ujisikie Unapendwa','Talk about the small things that make you feel most loved.','Zungumzieni mambo madogo yanayowafanya mjisikie kupendwa zaidi.'),
  ('Deep Conversations','Childhood Memories','Kumbukumbu za Utotoni','Tell each other your favorite story from childhood.','Simulianeni hadithi mnayoipenda zaidi ya utotoni.'),
  ('Deep Conversations','Our Shared Values','Maadili Tunayoshiriki','Name three values that matter most to you and why.','Taja maadili matatu muhimu zaidi kwako na sababu zake.'),
  ('Deep Conversations','Talking About Money','Kuzungumzia Pesa','Discuss how you each feel about saving, spending and goals.','Zungumzieni mnavyojisikia kuhusu kuweka akiba, matumizi na malengo.'),
  ('Deep Conversations','What I Admire in You','Ninachokiheshimu Kwako','Share the qualities you admire most in each other.','Shirikisheni sifa mnazozithamini zaidi kwa kila mmoja.'),
  ('Deep Conversations','Lessons From Hard Times','Mafunzo ya Nyakati Ngumu','Talk about a tough time and what it taught you.','Zungumzieni wakati mgumu na kilichofundishwa nacho.'),
  ('Deep Conversations','Forgiveness','Msamaha','Discuss what forgiveness means to each of you.','Zungumzieni msamaha unamaanisha nini kwa kila mmoja.'),
  ('Deep Conversations','Family Traditions','Mila za Familia','Share the traditions you want to keep or start together.','Shirikisheni mila mnazotaka kuziendeleza au kuanzisha pamoja.'),
  ('Deep Conversations','A Perfect Day','Siku Kamilifu','Describe your perfect day from morning to night.','Elezeni siku yenu kamilifu kuanzia asubuhi hadi usiku.'),
  ('Deep Conversations','Where We Want to Live','Tunapotaka Kuishi','Talk about the place and home you each imagine.','Zungumzieni mahali na nyumba ambayo kila mmoja anaifikiria.'),
  ('Deep Conversations','What Stress Looks Like','Msongo wa Mawazo Unavyoonekana','Explain how you act when stressed and what helps.','Elezeni mnavyotenda mkiwa na msongo na kinachosaidia.'),
  ('Deep Conversations','Personal Boundaries','Mipaka Binafsi','Talk openly about what you each need to feel respected.','Zungumzieni wazi mnachohitaji ili mjisikie kuheshimiwa.'),
  ('Deep Conversations','Gratitude Round','Mzunguko wa Shukrani','Take turns naming things in your life you are grateful for.','Zamu kwa zamu, taja mambo unayoyashukuru maishani.'),
  ('Deep Conversations','Beliefs and Faith','Imani na Dini','Share what your beliefs mean to you, with respect and curiosity.','Shirikisheni imani yenu inamaanisha nini kwenu, kwa heshima.'),
  ('Deep Conversations','How We Handle Conflict','Tunavyoshughulikia Migogoro','Talk about what works and what doesn''t when you disagree.','Zungumzieni kinachofanya kazi na kisichofanya mnapotofautiana.'),
  ('Deep Conversations','Something Unsaid','Jambo Ambalo Halijasemwa','Share something you have wanted to say but haven''t yet.','Shirikisha jambo ulilotaka kusema lakini bado hujalisema.'),
  ('Deep Conversations','What We Want to Be Remembered For','Tunachotaka Kukumbukwa Kwacho','Imagine the legacy you want to leave together.','Fikirieni urithi mnaotaka kuuacha pamoja.'),
  ('Deep Conversations','One Thing I''m Proud Of','Jambo Ninalolijivunia','Share an achievement you are proud of and why it matters.','Shirikisha mafanikio unayojivunia na kwa nini ni muhimu.'),
  ('Fun Games','Two Truths and a Lie','Ukweli Mbili na Uongo Mmoja','Tell three things about yourself; your partner guesses the lie.','Sema mambo matatu kukuhusu; mwenza abashiri uongo.'),
  ('Fun Games','Couples Quiz','Mtihani wa Wapenzi','Ask each other ten questions about favorites and see who knows more.','Ulizianeni maswali kumi kuhusu vipendwa na kuona nani anajua zaidi.'),
  ('Fun Games','Twenty Questions','Maswali Ishirini','Think of something and let your partner guess with yes/no questions.','Fikiria kitu na mwenza abashiri kwa maswali ya ndiyo au hapana.'),
  ('Fun Games','Charades','Igizo Bubu','Act out movies or songs without speaking.','Igizeni filamu au nyimbo bila kuongea.'),
  ('Fun Games','Would You Rather','Ungependelea Lipi','Choose between funny and tricky options and explain why.','Chagueni kati ya machaguo ya kuchekesha na magumu na kueleza sababu.'),
  ('Fun Games','Card Game Night','Usiku wa Karata','Play your favorite card game with a small friendly prize.','Chezeni mchezo wa karata mnaoupenda na zawadi ndogo.'),
  ('Fun Games','Draw and Guess','Chora na Bashiri','Take turns drawing while the other guesses the word.','Zamu kwa zamu, chora huku mwenzako akibashiri neno.'),
  ('Fun Games','Board Game Showdown','Pambano la Mchezo wa Ubao','Pick a board game and play best of three.','Chagueni mchezo wa ubao na kucheza mara tatu.'),
  ('Fun Games','Clean Truth or Dare','Ukweli au Kuthubutu','Ask light, funny questions and give playful dares.','Uliza maswali mepesi ya kuchekesha na kutoa changamoto za kufurahisha.'),
  ('Fun Games','Memory Match','Mchezo wa Kumbukumbu','Test who remembers more details of your past dates.','Jaribuni nani anakumbuka maelezo zaidi ya miadi yenu ya zamani.'),
  ('Fun Games','Hide and Seek','Kujificha na Kutafuta','Play like kids around the house and laugh a lot.','Chezeni kama watoto nyumbani na kucheka sana.'),
  ('Fun Games','Home Karaoke','Karaoke Nyumbani','Sing your favorite songs together, no judging.','Imbeni nyimbo mnazozipenda pamoja, bila kuhukumiana.'),
  ('Fun Games','Trivia Battle','Vita vya Maswali','Make up trivia questions for each other and keep score.','Tungeni maswali ya maarifa na kuhesabu pointi.'),
  ('Fun Games','Lip-Sync Battle','Pambano la Kuigiza Nyimbo','Perform a song with big gestures and let the other judge.','Igiza wimbo kwa miondoko mikubwa na mwenzako atoe hukumu.'),
  ('Fun Games','Kitchen Cook-Off','Mashindano ya Kupika','Cook with the same ingredients and taste each other''s dish.','Pikeni kwa viungo vilevile na kuonja chakula cha mwenzako.'),
  ('Fun Games','Word Chain','Mnyororo wa Maneno','Say a word starting with the last letter of your partner''s word.','Taja neno linaloanza na herufi ya mwisho ya neno la mwenza.'),
  ('Fun Games','Guess the Song','Bashiri Wimbo','Hum or play a few seconds and let your partner name the song.','Imba au cheza sekunde chache na mwenza ataje wimbo.'),
  ('Fun Games','Paper Plane Contest','Mashindano ya Ndege za Karatasi','Fold planes and see whose flies farthest.','Tengenezeni ndege za karatasi na kuona ya nani inaruka mbali zaidi.'),
  ('Fun Games','Pillow Fort','Ngome ya Mito','Build a fort in the living room and spend the evening inside.','Jengeni ngome ya mito sebuleni na kukaa ndani jioni nzima.'),
  ('Fun Games','Scavenger Hunt','Kutafuta Hazina','Hide small clues around the house leading to a surprise.','Ficheni vidokezo vidogo nyumbani vinavyoongoza kwenye mshangao.'),
  ('Couple Challenges','Seven Days of Compliments','Siku Saba za Pongezi','Give your partner one sincere compliment every day for a week.','Mpe mwenza wako pongezi moja ya dhati kila siku kwa wiki.'),
  ('Couple Challenges','Phone-Free Dinner','Chakula Bila Simu','Eat dinner together with all phones out of reach.','Kuleni chakula pamoja simu zikiwa mbali.'),
  ('Couple Challenges','Thirty-Day Walks','Matembezi ya Siku Thelathini','Walk together for at least ten minutes every day for a month.','Tembeeni pamoja angalau dakika kumi kila siku kwa mwezi.'),
  ('Couple Challenges','New Recipe Weekly','Mapishi Mapya Kila Wiki','Cook one recipe you''ve never tried every week.','Pikeni mapishi mapya kila wiki mliyowahi kujaribu.'),
  ('Couple Challenges','Learn a Dance','Jifunzeni Dansi','Learn a simple dance routine together in one week.','Jifunzeni dansi rahisi pamoja ndani ya wiki moja.'),
  ('Couple Challenges','Save Together','Wekeni Akiba Pamoja','Pick a small goal and save a little every week.','Chagueni lengo dogo na kuweka akiba kidogo kila wiki.'),
  ('Couple Challenges','Fitness Together','Mazoezi Pamoja','Do a short workout together three times this week.','Fanyeni mazoezi mafupi pamoja mara tatu wiki hii.'),
  ('Couple Challenges','Learn a New Language','Jifunzeni Lugha Mpya','Learn five new words in a new language every day.','Jifunzeni maneno matano mapya ya lugha mpya kila siku.'),
  ('Couple Challenges','Day Without Complaining','Siku Bila Kulalamika','Go 24 hours without complaining and see how it feels.','Kaeni saa 24 bila kulalamika na kuona inavyokuwa.'),
  ('Couple Challenges','Gratitude Jar','Chupa ya Shukrani','Drop a note of thanks in a jar daily for thirty days.','Weka ujumbe wa shukrani kwenye chupa kila siku kwa siku thelathini.'),
  ('Couple Challenges','Digital Detox Evening','Jioni Bila Teknolojia','Spend one evening with no screens at all.','Tumieni jioni moja bila skrini yoyote.'),
  ('Couple Challenges','Read the Same Book','Someni Kitabu Kimoja','Read a book together and discuss a chapter each night.','Someni kitabu kimoja na kujadili sura moja kila usiku.'),
  ('Couple Challenges','Swap Chores','Badilishaneni Kazi','Do each other''s chores for a day with a smile.','Fanyeni kazi za mwenzako kwa siku moja kwa furaha.'),
  ('Couple Challenges','Surprise Each Other','Shangazaneni','Plan one small surprise for your partner this week.','Panga mshangao mmoja mdogo kwa mwenza wako wiki hii.'),
  ('Couple Challenges','Sunrise Together','Macheo Pamoja','Wake up early once and watch the sunrise together.','Amkeni mapema mara moja na kutazama macheo pamoja.'),
  ('Couple Challenges','Skill Swap','Fundishaneni Ujuzi','Teach each other a skill you are good at.','Fundishaneni ujuzi ambao kila mmoja anaumudu.'),
  ('Couple Challenges','No-Complaint Budget Week','Wiki ya Bajeti Makini','Spend only on essentials for a week and see what you save.','Tumieni pesa kwa mahitaji muhimu tu kwa wiki na kuona mnachoweka.'),
  ('Couple Challenges','Compliment in Public','Pongezi Hadharani','Praise your partner in front of family or friends.','Msifu mwenza wako mbele ya familia au marafiki.'),
  ('Couple Challenges','Random Acts of Kindness','Matendo ya Wema','Do three kind things for others together this week.','Fanyeni mambo matatu ya wema kwa wengine pamoja wiki hii.'),
  ('Couple Challenges','No-TV Week','Wiki Bila Televisheni','Replace TV time with talking, games or walks for a week.','Badilisheni muda wa TV na mazungumzo, michezo au matembezi kwa wiki.'),
  ('Love & Appreciation','Thank-You List','Orodha ya Shukrani','Write ten things you thank your partner for and read them out.','Andika mambo kumi unayomshukuru mwenza wako na kuyasoma kwa sauti.'),
  ('Love & Appreciation','Appreciation Jar','Chupa ya Kuthamini','Add a note about what you value each time it comes to mind.','Ongeza ujumbe kuhusu unachothamini kila kinapokujia akilini.'),
  ('Love & Appreciation','Morning Compliment','Pongezi ya Asubuhi','Start the day by telling your partner one thing you love about them.','Anza siku kwa kumwambia mwenza jambo moja unalompendea.'),
  ('Love & Appreciation','Our Favorite Things','Mambo Tunayoyapenda Kuhusu Sisi','List what you love most about being a couple.','Orodhesheni mnachopenda zaidi kuhusu kuwa wapenzi.'),
  ('Love & Appreciation','Gratitude Letter','Barua ya Shukrani','Write a heartfelt letter thanking your partner for being there.','Andika barua ya moyoni kumshukuru mwenza wako kwa kuwepo.'),
  ('Love & Appreciation','Celebrate Small Wins','Sherehekea Mafanikio Madogo','Celebrate something small your partner achieved this week.','Sherehekea jambo dogo alilofanikisha mwenza wako wiki hii.'),
  ('Love & Appreciation','Love Language Talk','Mazungumzo ya Lugha za Mapenzi','Discover how each of you best gives and receives love.','Gundueni kila mmoja anavyotoa na kupokea mapenzi vizuri zaidi.'),
  ('Love & Appreciation','Memory Box of Love','Sanduku la Kumbukumbu za Mapenzi','Collect tickets, notes and small keepsakes in one box.','Kusanyeni tiketi, ujumbe na vitu vidogo vya kumbukumbu kwenye sanduku moja.'),
  ('Love & Appreciation','Midday Thank-You Text','Ujumbe wa Shukrani wa Mchana','Send a sincere thank-you message in the middle of the day.','Tuma ujumbe wa shukrani wa dhati katikati ya siku.'),
  ('Love & Appreciation','Words of Affirmation Night','Usiku wa Maneno ya Kutia Moyo','Take turns saying encouraging words to each other.','Zamu kwa zamu, semeni maneno ya kutia moyo.'),
  ('Love & Appreciation','Foot Rub Evening','Jioni ya Kusugua Miguu','Offer a gentle foot rub after a long day.','Msugue mwenza miguu kwa upole baada ya siku ndefu.'),
  ('Love & Appreciation','Do Their Chore','Fanya Kazi Yake','Quietly take care of a chore your partner usually does.','Fanya kimya kimya kazi ambayo mwenza wako kwa kawaida huifanya.'),
  ('Love & Appreciation','Framed Favorite Photo','Picha Unayoipenda Kwenye Fremu','Print a favorite photo of you two and frame it.','Chapisha picha mnayoipenda ya wawili na kuiweka kwenye fremu.'),
  ('Love & Appreciation','Strengths List','Orodha ya Nguvu','Write the strengths you see in your partner and share them.','Andika nguvu unazoziona kwa mwenza wako na kumshirikisha.'),
  ('Love & Appreciation','Small Surprise Gift','Zawadi Ndogo ya Mshangao','Give a small, thoughtful gift for no special reason.','Toa zawadi ndogo yenye mawazo bila sababu maalum.'),
  ('Love & Appreciation','Love Coupon Book','Kijitabu cha Kuponi za Mapenzi','Make coupons like ''one hug'' or ''one dinner'' to redeem.','Tengeneza kuponi kama ''kumbatio moja'' au ''chakula kimoja'' za kutumia.'),
  ('Love & Appreciation','Toast to Us','Kunywa kwa Heshima Yetu','Raise a glass and toast what you have built together.','Inueni glasi na kunywa kwa heshima ya mliyojenga pamoja.'),
  ('Love & Appreciation','Thank Their Family','Washukuru Familia Yake','Send a kind message to someone who supports your partner.','Tuma ujumbe wa wema kwa mtu anayemsaidia mwenza wako.'),
  ('Love & Appreciation','Highlight Reel','Mambo Bora ya Mwaka','Share your favorite moments together from the past year.','Shirikisheni nyakati bora mlizokuwa nazo mwaka uliopita.'),
  ('Love & Appreciation','Daily Thank You Ritual','Desturi ya Shukrani ya Kila Siku','Say one thank-you to each other before bed every night.','Semeni asante moja kwa kila mmoja kabla ya kulala kila usiku.'),
  ('Memories','Photo Album Evening','Jioni ya Albamu ya Picha','Look through old photos and tell the story behind each one.','Tazameni picha za zamani na kusimulia hadithi ya kila moja.'),
  ('Memories','Relationship Timeline','Ratiba ya Safari Yetu','Draw a timeline of your biggest moments as a couple.','Chorae ratiba ya matukio makubwa ya uhusiano wenu.'),
  ('Memories','First Impressions','Maoni ya Kwanza','Share what you first thought when you met.','Shirikisheni mlichofikiri mlipokutana mara ya kwanza.'),
  ('Memories','Funniest Moment','Tukio la Kuchekesha Zaidi','Relive the funniest thing that ever happened to you two.','Kumbukeni jambo la kuchekesha zaidi lililowahi kuwatokea.'),
  ('Memories','Old Messages','Jumbe za Zamani','Read some of your first messages and laugh together.','Someni baadhi ya jumbe zenu za kwanza na kucheka pamoja.'),
  ('Memories','Revisit a Special Place','Tembeleeni Mahali Maalum','Go back to a place that holds a good memory.','Rudini mahali penye kumbukumbu nzuri.'),
  ('Memories','Time Capsule','Kapsuli ya Wakati','Write notes and objects to open together in a year.','Andikeni ujumbe na kuweka vitu vya kufungua pamoja baada ya mwaka.'),
  ('Memories','Memory Jar','Chupa ya Kumbukumbu','Write down good moments through the year and read them at the end.','Andikeni nyakati nzuri mwaka mzima na kuzisoma mwishoni.'),
  ('Memories','Video Montage','Video ya Kumbukumbu','Put photos and clips of your journey into one short video.','Unganisheni picha na video za safari yenu kuwa video moja fupi.'),
  ('Memories','Recreate an Old Photo','Rudieni Picha ya Zamani','Pose again like in an old photo and compare.','Pozini tena kama kwenye picha ya zamani na kulinganisha.'),
  ('Memories','Trip Recap','Kumbuka Safari Yetu','Talk about your favorite trip and what you loved most.','Zungumzieni safari mnayoipenda zaidi na kilichowapendeza.'),
  ('Memories','Our Song','Wimbo Wetu','Pick the song that reminds you of each other and play it.','Chagueni wimbo unaowakumbusha kila mmoja na kuucheza.'),
  ('Memories','Scrapbook','Kitabu cha Kumbukumbu','Glue photos, tickets and notes into a scrapbook together.','Gandisheni picha, tiketi na ujumbe kwenye kitabu pamoja.'),
  ('Memories','Anniversary Toast','Kunywa Kwa Maadhimisho','Raise a glass and share a favorite memory from the year.','Inueni glasi na kushirikisha kumbukumbu mnayoipenda ya mwaka.'),
  ('Memories','Letter to Future Us','Barua kwa Sisi wa Baadaye','Write a letter to read together on your next anniversary.','Andikeni barua ya kusoma pamoja kwenye maadhimisho yajayo.'),
  ('Memories','How We Met','Jinsi Tulivyokutana','Tell the story of how you met from your own point of view.','Simulia jinsi mlivyokutana kwa mtazamo wako.'),
  ('Memories','Keepsake Box','Sanduku la Zawadi za Kumbukumbu','Collect small items that remind you of special days.','Kusanyeni vitu vidogo vinavyowakumbusha siku maalum.'),
  ('Memories','Childhood Photos','Picha za Utotoni','Share photos from when you were little and tell the stories.','Shirikisheni picha za utotoni na kusimulia hadithi zake.'),
  ('Memories','Favorite Meals Memory','Kumbukumbu za Vyakula','Remember the best meals you''ve shared and cook one again.','Kumbukeni vyakula bora mlivyokula pamoja na kupika kimoja tena.'),
  ('Memories','List Our Milestones','Orodha ya Hatua Zetu','Write the milestones you''ve reached together so far.','Andikeni hatua mlizofikia pamoja hadi sasa.'),
  ('Future','Vision Board','Ubao wa Maono','Make a collage of what you want your future to look like.','Tengenezeni kolaji ya mnavyotaka maisha yenu ya baadaye yawe.'),
  ('Future','Five-Year Plan','Mpango wa Miaka Mitano','Write shared goals for the next five years.','Andikeni malengo ya pamoja ya miaka mitano ijayo.'),
  ('Future','Couple Bucket List','Orodha ya Mambo ya Kufanya','List twenty things you want to do together.','Orodheshani mambo ishirini mnayotaka kufanya pamoja.'),
  ('Future','Dream Home','Nyumba ya Ndoto','Describe or sketch the home you want to live in.','Elezeni au kuchora nyumba mnayotaka kuishi.'),
  ('Future','Travel Wish List','Orodha ya Safari','Pick five places you want to visit and why.','Chagueni sehemu tano mnazotaka kutembelea na sababu.'),
  ('Future','Savings Goal','Lengo la Akiba','Choose something to save for and set a monthly amount.','Chagueni kitu cha kuwekea akiba na kiasi cha kila mwezi.'),
  ('Future','Business or Project Idea','Wazo la Biashara au Mradi','Brainstorm a project you could build together.','Fikirieni mradi mnaoweza kujenga pamoja.'),
  ('Future','Growing Old Together','Kuzeeka Pamoja','Picture your life together as older people.','Fikirieni maisha yenu pamoja mkiwa wazee.'),
  ('Future','Family Plans','Mipango ya Familia','Talk about the family life you each hope for.','Zungumzieni maisha ya familia ambayo kila mmoja anatarajia.'),
  ('Future','Yearly Goals','Malengo ya Mwaka','Set three goals for the year, one each and one together.','Wekeni malengo matatu ya mwaka, moja kila mmoja na moja la pamoja.'),
  ('Future','Date Night Calendar','Kalenda ya Miadi','Plan one date night for every month of the year.','Panga miadi moja kwa kila mwezi wa mwaka.'),
  ('Future','Learn Something New','Jifunzeni Kitu Kipya','Choose a class or skill to learn together this year.','Chagueni darasa au ujuzi wa kujifunza pamoja mwaka huu.'),
  ('Future','Home Makeover Ideas','Mawazo ya Kupamba Nyumba','Plan small changes that make your space feel like yours.','Panga mabadiliko madogo yanayofanya nyumba iwe yenu.'),
  ('Future','Dream Vacation','Likizo ya Ndoto','Plan a pretend trip with budget, dates and places.','Panga safari ya kuigiza ikiwa na bajeti, tarehe na sehemu.'),
  ('Future','Letter to Ten Years From Now','Barua ya Miaka Kumi Ijayo','Write what you hope for and seal it for later.','Andikeni mnachotarajia na kuifunga kwa baadaye.'),
  ('Future','Plan the Next Anniversary','Panga Maadhimisho Yajayo','Decide how you''d like to celebrate your next anniversary.','Amueni mnavyotaka kusherehekea maadhimisho yajayo.'),
  ('Future','Giving Back Goals','Malengo ya Kusaidia Wengine','Choose a cause you''d like to support together.','Chagueni jambo mnalotaka kulisaidia pamoja.'),
  ('Future','Support Each Other''s Career','Saidianeni Kazini','Share career dreams and how you can help each other.','Shirikisheni ndoto za kazi na jinsi ya kusaidiana.'),
  ('Future','Health Goals','Malengo ya Afya','Set healthy habits you can build together.','Wekeni tabia nzuri za afya mnazoweza kujenga pamoja.'),
  ('Future','Our Future Values','Maadili ya Maisha Yetu Ya Baadaye','Write the principles you want your future to be built on.','Andikeni misingi mnayotaka maisha yenu ya baadaye yajengwe juu yake.'),
  ('Activities','Cooking Class at Home','Darasa la Kupika Nyumbani','Follow a new recipe together step by step.','Fuateni mapishi mapya pamoja hatua kwa hatua.'),
  ('Activities','Nature Hike','Matembezi ya Mlimani au Porini','Pick a trail, pack water and enjoy the view.','Chagueni njia, chukueni maji na kufurahia mandhari.'),
  ('Activities','Bike Ride','Kuendesha Baiskeli','Ride to a place you have never visited.','Endesheni baiskeli hadi mahali ambapo hamjawahi kufika.'),
  ('Activities','Beach Day','Siku ya Ufukweni','Swim, walk on the sand and watch the waves.','Ogeleeni, tembeeni mchangani na kutazama mawimbi.'),
  ('Activities','Museum or Gallery Visit','Tembelea Makumbusho','Explore a museum and share your favorite piece.','Tembeleeni makumbusho na kushirikisha kazi mnayoipenda.'),
  ('Activities','Pottery or Craft Session','Ufundi wa Mikono','Make something with your hands together.','Tengenezeni kitu kwa mikono yenu pamoja.'),
  ('Activities','Plant Something Together','Pandeni Kitu Pamoja','Plant a small garden or a tree and care for it.','Pandeni bustani ndogo au mti na kuutunza.'),
  ('Activities','Visit a Local Market','Tembelea Soko la Hapa','Wander the market and cook with what you find.','Zungukeni sokoni na kupika kwa mlichopata.'),
  ('Activities','Volunteer Together','Jitoleeni Pamoja','Spend a few hours helping others in your community.','Tumieni masaa machache kusaidia jamii yenu.'),
  ('Activities','Painting Evening','Jioni ya Kuchora','Paint or draw each other and laugh at the results.','Chorana au chora kila mmoja na kucheka matokeo.'),
  ('Activities','Sunset Picnic','Pikiniki ya Machweo','Bring snacks to a view and watch the sunset.','Chukueni vitafunwa mahali penye mandhari na kutazama machweo.'),
  ('Activities','Fishing Trip','Safari ya Kuvua Samaki','Relax by the water and see who catches more.','Pumzikeni kando ya maji na kuona nani atavua zaidi.'),
  ('Activities','Swimming Date','Miadi ya Kuogelea','Go for a swim or a splash at the pool.','Nendeni kuogelea au kucheza majini.'),
  ('Activities','Home Spa Day','Siku ya Spa Nyumbani','Create a relaxing spa at home with music and tea.','Tengenezeni spa ya kupumzika nyumbani kwa muziki na chai.'),
  ('Activities','Dance Class','Darasa la Dansi','Try a dance lesson or follow an online one.','Jaribuni somo la dansi au kufuata la mtandaoni.'),
  ('Activities','Day Trip','Safari ya Siku Moja','Pick a nearby town and explore it for a day.','Chagueni mji wa karibu na kuuchunguza kwa siku.'),
  ('Activities','Game Cafe or Arcade','Mkahawa wa Michezo','Play games at a cafe or arcade and cheer each other on.','Chezeni michezo mkahawani na kushangiliana.'),
  ('Activities','Photography Walk','Matembezi ya Kupiga Picha','Capture interesting things around your area.','Pigeni picha vitu vya kuvutia mtaani kwenu.'),
  ('Activities','Movie Marathon','Marathon ya Filamu','Pick a series or trilogy and watch it together.','Chagueni mfululizo wa filamu na kuutazama pamoja.'),
  ('Activities','Mini Road Trip','Safari Fupi ya Gari','Drive somewhere new with good music and snacks.','Endesheni hadi mahali papya mkiwa na muziki na vitafunwa.'),
  ('Communication','Ten Minutes of Listening','Dakika Kumi za Kusikiliza','One speaks for ten minutes, the other only listens, then swap.','Mmoja anaongea dakika kumi, mwingine anasikiliza tu, kisha mbadilishane.'),
  ('Communication','I-Feel Statements','Kauli za ''Najisikia''','Practice saying ''I feel... when... because...'' instead of blaming.','Zoeeni kusema ''Najisikia... pale... kwa sababu...'' badala ya kulaumu.'),
  ('Communication','Weekly Check-In','Mazungumzo ya Kila Wiki','Sit down weekly to share highs, lows and needs.','Kaeni kila wiki kushirikisha mazuri, magumu na mahitaji.'),
  ('Communication','Appreciate Before Asking','Shukuru Kabla ya Kuomba','Start any request with something you appreciate.','Anza ombi lolote kwa kitu unachokithamini.'),
  ('Communication','Calm Time-Out','Mapumziko ya Utulivu','Agree on a pause when things get heated, then return to talk.','Kubalianeni kupumzika mambo yakipamba moto kisha kurudi kuzungumza.'),
  ('Communication','Needs and Wants List','Orodha ya Mahitaji','Each write three needs and three wants and compare.','Kila mmoja aandike mahitaji matatu na matamanio matatu na kulinganisha.'),
  ('Communication','Mirror What You Heard','Rudia Ulichosikia','Repeat what your partner said before you answer.','Rudia mwenza alichosema kabla ya kujibu.'),
  ('Communication','Open Questions','Maswali Yaliyo Wazi','Ask ''what'' and ''how'' questions instead of yes/no ones.','Uliza maswali ya ''nini'' na ''vipi'' badala ya ndiyo au hapana.'),
  ('Communication','Five-Minute Daily Talk','Mazungumzo ya Dakika Tano Kila Siku','Talk for five minutes daily with no phones around.','Zungumzeni dakika tano kila siku bila simu karibu.'),
  ('Communication','Share a Worry','Shirikisha Wasiwasi','Tell your partner something worrying you and ask for support.','Mwambie mwenza jambo linalokusumbua na kuomba msaada.'),
  ('Communication','Say What You Need','Sema Unachohitaji','Practice asking clearly for what you need.','Zoea kuomba wazi unachohitaji.'),
  ('Communication','Repair Phrases','Maneno ya Kupatana','Agree on phrases to calm and reconnect after a fight.','Kubalianeni maneno ya kutuliza na kuungana tena baada ya ugomvi.'),
  ('Communication','Pause Signal','Ishara ya Kusimama','Pick a gentle word or gesture that means ''let''s pause''.','Chagueni neno au ishara laini inayomaanisha ''tusimame kidogo''.'),
  ('Communication','Emotion Check-In','Kuangalia Hisia','Name how you feel from a list of feelings and share why.','Taja unavyojisikia kutoka orodha ya hisia na kueleza sababu.'),
  ('Communication','Express Gratitude Daily','Toa Shukrani Kila Siku','Thank your partner for one thing every day.','Mshukuru mwenza kwa jambo moja kila siku.'),
  ('Communication','Schedule a Hard Talk','Panga Mazungumzo Magumu','Pick a calm time for difficult topics instead of ambushing.','Chagua wakati tulivu kwa mada ngumu badala ya kushtukiza.'),
  ('Communication','Body Language Awareness','Lugha ya Mwili','Notice how tone and posture change the message.','Tambua jinsi sauti na mwili vinavyobadilisha ujumbe.'),
  ('Communication','Kind Feedback','Maoni kwa Wema','Share a concern with something positive before and after.','Toa wasiwasi ukiwa na jambo zuri kabla na baada.'),
  ('Communication','Apologize Well','Omba Msamaha Vizuri','Say what you did, how it affected them and how you''ll change.','Sema ulichofanya, kilivyomuathiri na jinsi utakavyobadilika.'),
  ('Communication','Plan the Week Together','Pangeni Wiki Pamoja','Sit down Sunday to share schedules and make time for each other.','Kaeni Jumapili kushirikisha ratiba na kupanga muda wa kila mmoja.');
